    def f(self, x):
        # Ensure x is within bounds
        x = np.clip(x, -5.0, 5.0)

        # Sphere function component
        sphere = np.sum(x**2)

        # Multimodal component with multiple local minima
        multimodal = 0
        for i in range(self.dim):
